Here's a modern MSTest data-driven test class for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- DataRow: inline values for CalculateTotal ---

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(10.00, 3, 30.00, DisplayName = "Multiple items")]
    [DataRow(0.00, 5, 0.00, DisplayName = "Zero price")]
    [DataRow(19.99, 0, 0.00, DisplayName = "Zero quantity")]
    [DataRow(9.99, 2, 19.98, DisplayName = "Fractional price")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData with ValueTuples for ApplyDiscount ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithVariousDiscounts_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (0m, 50, 0m),
    ];

    // --- Edge case: invalid discount throws ---

    [TestMethod]
    [DataRow(-1)]
    [DataRow(101)]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRange(int percent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, percent));
    }
}
```

**Key practices used:**

- **Sealed class** for performance
- **DataRow** for simple inline cases (note: `decimal` isn't a compile-time constant, so `double` is cast)
- **DynamicData with ValueTuples** (MSTest 3.7+) for type-safe complex data
- **DisplayName** for readable test output
- **`Assert.ThrowsExactly`** instead of `[ExpectedException]`
- **AAA pattern** with clear naming (`Method_Scenario_Expected`)

For the project file, ensure you're on MSTest 3.7+:

```xml
<Project Sdk="MSTest.Sdk">
  <PropertyGroup>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
</Project>
```
